edits.before:
onClick (event) {
  if (event.target.closest(`[${ this.config.closeTrigger }]`)) {
    event.preventDefault()
    event.stopPropagation()
    this.closeModal(event)
  }
}

edits.after:
onClick (event) {
  const target = event.target;
  if (target.hasAttribute(this.config.closeTrigger)) {
    event.preventDefault()
    event.stopPropagation()
    this.closeModal(event)
    return;
  }
  // Prevent clicks inside the modal from bubbling to the overlay
  if (target.closest('.modal__container')) {
    event.stopPropagation()
  }
}
